s[8] += s[12]; s[4] ^= s[8]; s[4] = s[4].rotate_right(7);
s[1] += s[5] + m2; s[13] ^= s[1]; s[13] = ...rot16
s[9] += s[13]; s[5] ^= s[9]; s[5] rot12
s[1] += s[5] + m3; s[13] ^= s[1]; s[13] rot8
s[9] += s[13]; s[5] ^= s[9]; s[5] rot7
then columns (2,6,10,14), (3,7,11,15)
