```rust
impl Hasher {
    fn finalize(&self, out_slice) {
        let mut output = self.chunk_state.output();
        if self.cv_stack.len() > 0 {
            let mut parent_output = parent_output(self.cv_stack.last(), output.chaining_value(), &self.key, self.flags);
            while self.cv_stack.len() > 1 {
