                parent_output = parent_output(self.cv_stack.pop(), parent_output.chaining_value(), ...);
            }
            output = parent_output;
        }
        output.root_output_bytes(out_slice);
    }
}
```
And Output::root_output_bytes: counter += 1 for each 64-byte block of output; flags |= ROOT. So:
```rust
fn root_output_bytes(&self, out_slice) {
    let mut output_block_counter = 0;
    for out_block in out_slice.chunks_mut(2*OUT_LEN) {
        let words = compress(self.input_chaining_value, self.block_words, self.counter + output_block_counter, self.block_len, self.flags | ROOT);
        for (word, out_word) in words.iter().zip(out_block.chunks_mut(4)) { out_word.copy_from_slice(&word.to_le_bytes()) }
        output_block_counter += 1;
    }
}
```
So the seek offset maps to output_block_counter = seek / 64 and the byte offset within. Since --seek is supported, b3sum uses OutputReader with seek.

Keyed mode: key = 32 bytes → 8 u32 LE words → initial chaining value = key, and flags |= KEYED_HASH.
Derive key mode: two-phase: first hash the context string as a chunk with DERIVE_KEY_CONTEXT flag (and input_chaining_value = key_words = the "blake3 context key" = IV), then the resulting chaining value becomes the input chaining value for the key material hash with DERIVE_KEY_MATERIAL flag.

Specifically:
```rust
fn new_derive_key(context: &str) -> Hasher {
    let context_hasher = {
        let mut context_hasher = Self::new_internal(key_words, DERIVE_KEY_CONTEXT);
        context_hasher.update(context.as_bytes());
        context_hasher
    };
    let mut derive_key_hasher = Self::new_internal(context_hasher.finalize().to_words(), DERIVE_KEY_MATERIAL);
    derive_key_hasher
}
```
where key_words = IV. And finalize of the context hasher gives 32 bytes → 8 words → used as the initial CV for the key material hashing. And the flags: DERIVE_KEY_CONTEXT for the context hash, DERIVE_KEY_MATERIAL for the material hash. Note DERIVE_KEY_MATERIAL = 64 = DERIVE_KEY_CONTEXT(32)*2.

Note: the context hash is a "root" hash (no extra flags needed since it's finalized with ROOT).

