pub fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jaro_distance = generic_jaro(&a.chars().collect::<Vec<_>>(), &b.chars().collect::<Vec<_>>());
    // Don't limit the length of the common prefix
    let prefix_length = a.chars().zip(b.chars()).take_while(|(ac, bc)| ac == bc).count();
    let jaro_winkler_distance = jaro_distance + (0.1 * prefix_length as f64 * (1.0 - jaro_distance));
    jaro_winkler_distance.clamp(0.0, 1.0)
}
```
