//! BLAKE3 core (from-scratch implementation).
pub const OUT_LEN: usize = 32;
pub const KEY_LEN: usize = 32;
const BLOCK_LEN: usize = 64;
const CHUNK_LEN: usize = 1024;

const CHUNK_START: u32 = 1 << 0;
const CHUNK_END: u32 = 1 << 1;
const PARENT: u32 = 1 << 2;
const ROOT: u32 = 1 << 3;
const KEYED_HASH: u32 = 1 << 4;
const DERIVE_KEY_CONTEXT: u32 = 1 << 5;
const DERIVE_KEY_MATERIAL: u32 = 1 << 6;

// NOTE: these IV words need verification against the target binary
// (see AGENT_REPORT.md blocker).
const IV: [u32; 8] = [
    0x6A09E667, 0xBB67AE85, 0x3C6C37A2, 0xA54FF53A,
    0x510E527F, 0x9B05688C, 0x1F83D9FB, 0x5BE0CD19,
];

const MSG_PERMUTATION: [usize; 16] = [2, 6, 3, 10, 7, 0, 4, 13, 1, 11, 12, 5, 9, 14, 15, 8];

#[inline(always)]
fn g(s: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize, mx: u32, my: u32) {
    s[a] = s[a].wrapping_add(s[b]).wrapping_add(mx);
    s[d] = (s[d] ^ s[a]).rotate_right(16);
    s[c] = s[c].wrapping_add(s[d]);
    s[b] = (s[b] ^ s[c]).rotate_right(12);
    s[a] = s[a].wrapping_add(s[b]).wrapping_add(my);
    s[d] = (s[d] ^ s[a]).rotate_right(8);
    s[c] = s[c].wrapping_add(s[d]);
    s[b] = (s[b] ^ s[c]).rotate_right(7);
}

#[inline(always)]
fn round(s: &mut [u32; 16], m: &[u32; 16]) {
    g(s, 0, 4, 8, 12, m[0], m[1]);
    g(s, 1, 5, 9, 13, m[2], m[3]);
    g(s, 2, 6, 10, 14, m[4], m[5]);
    g(s, 3, 7, 11, 15, m[6], m[7]);
    g(s, 0, 5, 10, 15, m[8], m[9]);
    g(s, 1, 6, 11, 12, m[10], m[11]);
    g(s, 2, 7, 8, 13, m[12], m[13]);
    g(s, 3, 4, 9, 14, m[14], m[15]);
}

fn permute(m: &mut [u32; 16]) {
    let mut p = [0u32; 16];
    for i in 0..16 { p[i] = m[MSG_PERMUTATION[i]]; }
    *m = p;
}

pub fn compress(pre_h: &[u32; 8], pre_block: &[u32; 16], counter: u64, block_len: u32, flags: u32) -> [u32; 16] {
    let mut block = *pre_block;
    block[12] = counter as u32;
    block[13] = (counter >> 32) as u32;
    block[14] = block_len;
    block[15] = flags;
    let mut state = [
        pre_h[0], pre_h[1], pre_h[2], pre_h[3], pre_h[4], pre_h[5], pre_h[6], pre_h[7],
        block[0], block[1], block[2], block[3], block[4], block[5], block[6], block[7],
    ];
    let mut m = block;
    for r in 0..7 {
        round(&mut state, &m);
        if r < 6 { permute(&mut m); }
    }
    let mut out = [0u32; 16];
    for i in 0..8 {
        out[i] = state[i] ^ state[i + 8];
        out[i + 8] = pre_h[i] ^ state[i + 8];
    }
    out
}

#[derive(Clone)]
pub struct Output {
    pub input_chaining_value: [u32; 8],
    pub block_words: [u32; 16],
    pub counter: u64,
    pub block_len: u32,
    pub flags: u32,
}

impl Output {
    pub fn chaining_value(&self) -> [u32; 8] {
        let words = compress(&self.input_chaining_value, &self.block_words, self.counter, self.block_len, self.flags);
        let mut cv = [0u32; 8];
        cv.copy_from_slice(&words[0..8]);
        cv
    }
    /// Extended output starting at byte offset `seek`.
    pub fn root_output_bytes(&self, seek: u64, out: &mut [u8]) {
        let mut counter = self.counter + seek / 64;
        let mut skip = (seek % 64) as usize;
        for chunk in out.chunks_mut(64) {
            let words = compress(&self.input_chaining_value, &self.block_words, counter, self.block_len, self.flags | ROOT);
            let mut bytes = [0u8; 64];
            for i in 0..16 { bytes[4 * i..4 * i + 4].copy_from_slice(&words[i].to_le_bytes()); }
            let n = chunk.len();
            chunk.copy_from_slice(&bytes[skip..skip + n]);
            skip = 0;
            counter += 1;
        }
    }
}

fn parent_output(left: [u32; 8], right: [u32; 8], key_words: [u32; 8], flags: u32) -> Output {
    let mut block_words = [0u32; 16];
    block_words[0..8].copy_from_slice(&left);
    block_words[8..16].copy_from_slice(&right);
    Output { input_chaining_value: key_words, block_words, counter: 0, block_len: BLOCK_LEN as u32, flags: flags | PARENT }
}

#[derive(Clone)]
struct ChunkState {
    cv: [u32; 8],
    chunk_counter: u64,
    block: [u32; 16],
    block_len: u8,
    blocks_committed: u8,
    flags: u32,
}

impl ChunkState {
    fn new(key_words: [u32; 8], chunk_counter: u64, flags: u32) -> Self {
        ChunkState { cv: key_words, chunk_counter, block: [0; 16], block_len: 0, blocks_committed: 0, flags }
    }
    fn len(&self) -> usize { BLOCK_LEN * self.blocks_committed as usize + self.block_len as usize }
    fn start_flag(&self) -> u32 { if self.blocks_committed == 0 { CHUNK_START } else { 0 } }
    fn update(&mut self, mut input: &[u8]) {
        while !input.is_empty() {
            if self.block_len as usize == BLOCK_LEN {
                let out = compress(&self.cv, &self.block, self.chunk_counter, BLOCK_LEN as u32, self.flags | self.start_flag());
                self.cv.copy_from_slice(&out[0..8]);
                self.block = [0; 16];
                self.block_len = 0;
                self.blocks_committed += 1;
            }
            let want = BLOCK_LEN - self.block_len as usize;
            let take = want.min(input.len());
            let start = self.block_len as usize;
            for i in 0..take { self.block[(start + i) / 4] |= (input[i] as u32) << (8 * ((start + i) % 4)); }
            self.block_len += take as u8;
            input = &input[take..];
        }
    }
    fn output(&self) -> Output {
        Output { input_chaining_value: self.cv, block_words: self.block, counter: self.chunk_counter, block_len: self.block_len as u32, flags: self.flags | CHUNK_END | self.start_flag() }
    }
}

#[derive(Clone)]
pub struct Hasher {
    chunk_state: ChunkState,
    key_words: [u32; 8],
    cv_stack: Vec<[u32; 8]>,
    flags: u32,
}

impl Hasher {
    fn new_internal(key_words: [u32; 8], flags: u32) -> Self {
        Hasher { chunk_state: ChunkState::new(key_words, 0, flags), key_words, cv_stack: Vec::new(), flags }
    }
    pub fn new() -> Self { Self::new_internal(IV, 0) }
    pub fn new_keyed(key: &[u8; KEY_LEN]) -> Self {
        let mut key_words = [0u32; 8];
        for i in 0..8 { key_words[i] = u32::from_le_bytes(key[4 * i..4 * i + 4].try_into().unwrap()); }
        Self::new_internal(key_words, KEYED_HASH)
    }
    pub fn new_derive_key(context: &str) -> Self {
        let mut context_hasher = Self::new_internal(IV, DERIVE_KEY_CONTEXT);
        context_hasher.update(context.as_bytes());
        let mut key = [0u8; 32];
        context_hasher.finalize_into(&mut key, 0);
        let mut key_words = [0u32; 8];
        for i in 0..8 { key_words[i] = u32::from_le_bytes(key[4 * i..4 * i + 4].try_into().unwrap()); }
        Self::new_internal(key_words, DERIVE_KEY_MATERIAL)
    }
    fn push(&mut self, cv: [u32; 8]) { self.cv_stack.push(cv); }
    fn pop(&mut self) -> [u32; 8] { self.cv_stack.pop().unwrap_or(self.key_words) }
    fn add_chunk_cv(&mut self, mut new_cv: [u32; 8], mut total: u64) {
        while total & 1 == 0 {
            let left = self.pop();
            new_cv = parent_output(left, new_cv, self.key_words, self.flags).chaining_value();
            total >>= 1;
        }
        self.push(new_cv);
    }
    pub fn update(&mut self, mut input: &[u8]) {
        while !input.is_empty() {
            if self.chunk_state.len() == CHUNK_LEN {
                let chunk_cv = self.chunk_state.output().chaining_value();
                let total = self.chunk_state.chunk_counter + 1;
                self.add_chunk_cv(chunk_cv, total);
                self.chunk_state = ChunkState::new(self.key_words, total, self.flags);
            }
            let want = CHUNK_LEN - self.chunk_state.len();
            let take = want.min(input.len());
            self.chunk_state.update(&input[..take]);
            input = &input[take..];
        }
    }
    fn finalize_output(&self) -> Output {
        let mut output = self.chunk_state.output();
        let mut stack = self.cv_stack.clone();
        while let Some(left) = stack.pop() {
            let right = output.chaining_value();
            output = parent_output(left, right, self.key_words, self.flags);
        }
        output
    }
    /// Writes `out.len()` output bytes starting at byte offset `seek`.
    pub fn finalize_into(&self, out: &mut [u8], seek: u64) {
        self.finalize_output().root_output_bytes(seek, out);
    }
    pub fn finalize(&self, seek: u64, len: usize) -> Vec<u8> {
        let mut out = vec![0u8; len];
        self.finalize_into(&mut out, seek);
        out
    }
}
